select public.upsert_bank_question($json${"id":"pent-easy-001","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":2,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"De que formou Deus o primeiro homem?","bible_ref":"Génesis 2:7","verse_text":"Formou, pois, o SENHOR Deus ao homem do pó da terra, e assoprou em seu nariz sopro de vida; e foi o homem em alma vivente."},"fr":{"prompt":"De quoi Dieu a-t-il formé le premier homme ?","bible_ref":"Genèse 2:7","verse_text":"L’Éternel Dieu forma l’homme de la poussière de la terre, il souffla dans ses narines un souffle de vie et l’homme devint un être vivant."},"en":{"prompt":"What did God form the first man from?","bible_ref":"Genesis 2:7","verse_text":"And the LORD God formed man of the dust of the ground, and breathed into his nostrils the breath of life; and man became a living soul."},"es":{"prompt":"¿De qué formó Dios al primer hombre?","bible_ref":"Génesis 2:7","verse_text":"Formó, pues, Jehová Dios al hombre del polvo de la tierra, y alentó en su nariz soplo de vida; y fué el hombre en alma viviente."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Do pó da terra"},"fr":{"text":"De la poussière de la terre"},"en":{"text":"The dust of the ground"},"es":{"text":"Del polvo de la tierra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De uma pedra"},"fr":{"text":"D’une pierre"},"en":{"text":"A stone"},"es":{"text":"De una piedra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De uma árvore"},"fr":{"text":"D’un arbre"},"en":{"text":"A tree"},"es":{"text":"De un árbol"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Da água do mar"},"fr":{"text":"De l’eau de la mer"},"en":{"text":"Sea water"},"es":{"text":"Del agua del mar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-002","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":2,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"De que parte de Adão fez Deus a mulher?","bible_ref":"Génesis 2:22","verse_text":"E da costela que o SENHOR Deus tomou do homem, fez uma mulher, e trouxe-a ao homem."},"fr":{"prompt":"De quelle partie d’Adam Dieu a-t-il fait la femme ?","bible_ref":"Genèse 2:22","verse_text":"L’Éternel Dieu forma une femme de la côte qu’il avait prise de l’homme, et il l’amena vers l’homme."},"en":{"prompt":"From what part of Adam did God make the woman?","bible_ref":"Genesis 2:22","verse_text":"And the rib, which the LORD God had taken from man, made he a woman, and brought her unto the man."},"es":{"prompt":"¿De qué parte de Adán hizo Dios a la mujer?","bible_ref":"Génesis 2:22","verse_text":"Y de la costilla que Jehová Dios tomó del hombre, hizo una mujer, y trájola al hombre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De uma costela"},"fr":{"text":"D’une côte"},"en":{"text":"A rib"},"es":{"text":"De una costilla"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Do pé"},"fr":{"text":"Du pied"},"en":{"text":"His foot"},"es":{"text":"Del pie"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Da mão"},"fr":{"text":"De la main"},"en":{"text":"His hand"},"es":{"text":"De la mano"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Do cabelo"},"fr":{"text":"Des cheveux"},"en":{"text":"His hair"},"es":{"text":"Del cabello"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-003","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":3,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Que animal falou com Eva no jardim?","bible_ref":"Génesis 3:1","verse_text":"Porém a serpente era astuta, mais que todos os animais do campo que o SENHOR Deus havia feito. E ela disse à mulher: Deus vos disse: Não comais de toda árvore do jardim?"},"fr":{"prompt":"Quel animal a parlé à Ève dans le jardin ?","bible_ref":"Genèse 3:1","verse_text":"Le serpent était le plus rusé de tous les animaux des champs, que l’Éternel Dieu avait faits. Il dit à la femme: Dieu a-t-il réellement dit: Vous ne mangerez pas de tous les arbres du jardin?"},"en":{"prompt":"Which animal spoke to Eve in the garden?","bible_ref":"Genesis 3:1","verse_text":"Now the serpent was more subtil than any beast of the field which the LORD God had made. And he said unto the woman, Yea, hath God said, Ye shall not eat of every tree of the garden?"},"es":{"prompt":"¿Qué animal habló con Eva en el huerto?","bible_ref":"Génesis 3:1","verse_text":"Empero la serpiente era astuta, más que todos los animales del campo que Jehová Dios había hecho; la cual dijo á la mujer: ¿Conque Dios os ha dicho: No comáis de todo árbol del huerto?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A serpente"},"fr":{"text":"Le serpent"},"en":{"text":"The serpent"},"es":{"text":"La serpiente"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O leão"},"fr":{"text":"Le lion"},"en":{"text":"The lion"},"es":{"text":"El león"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O corvo"},"fr":{"text":"Le corbeau"},"en":{"text":"The raven"},"es":{"text":"El cuervo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A raposa"},"fr":{"text":"Le renard"},"en":{"text":"The fox"},"es":{"text":"La zorra"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-004","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":4,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Quem matou o seu irmão Abel?","bible_ref":"Génesis 4:8","verse_text":"Depois Caim falou a seu irmão Abel; e aconteceu que, estando eles no campo, Caim se levantou contra seu irmão Abel, e o matou."},"fr":{"prompt":"Qui a tué son frère Abel ?","bible_ref":"Genèse 4:8","verse_text":"Cependant, Caïn adressa la parole à son frère Abel; mais, comme ils étaient dans les champs, Caïn se jeta sur son frère Abel, et le tua."},"en":{"prompt":"Who killed his brother Abel?","bible_ref":"Genesis 4:8","verse_text":"And Cain talked with Abel his brother: and it came to pass, when they were in the field, that Cain rose up against Abel his brother, and slew him."},"es":{"prompt":"¿Quién mató a su hermano Abel?","bible_ref":"Génesis 4:8","verse_text":"Y habló Caín á su hermano Abel: y aconteció que estando ellos en el campo, Caín se levantó contra su hermano Abel, y le mató."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Caim"},"fr":{"text":"Caïn"},"en":{"text":"Cain"},"es":{"text":"Caín"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Seth"},"en":{"text":"Seth"},"es":{"text":"Seth"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Noé"},"fr":{"text":"Noé"},"en":{"text":"Noah"},"es":{"text":"Noé"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Adão"},"fr":{"text":"Adam"},"en":{"text":"Adam"},"es":{"text":"Adam"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-005","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":6,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"O que mandou Deus Noé construir?","bible_ref":"Génesis 6:14","verse_text":"Faze-te uma arca de madeira de gôfer: farás aposentos na arca e a selarás com betume por dentro e por fora."},"fr":{"prompt":"Qu’est-ce que Dieu a demandé à Noé de construire ?","bible_ref":"Genèse 6:14","verse_text":"Fais-toi une arche de bois de gopher; tu disposeras cette arche en cellules, et tu l’enduiras de poix en dedans et en dehors."},"en":{"prompt":"What did God tell Noah to build?","bible_ref":"Genesis 6:14","verse_text":"Make thee an ark of gopher wood; rooms shalt thou make in the ark, and shalt pitch it within and without with pitch."},"es":{"prompt":"¿Qué mandó Dios a Noé construir?","bible_ref":"Génesis 6:14","verse_text":"Hazte un arca de madera de Gopher: harás aposentos en el arca, y la embetunarás con brea por dentro y por fuera."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma arca"},"fr":{"text":"Une arche"},"en":{"text":"An ark"},"es":{"text":"Un arca"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma torre"},"fr":{"text":"Une tour"},"en":{"text":"A tower"},"es":{"text":"Una torre"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um templo"},"fr":{"text":"Un temple"},"en":{"text":"A temple"},"es":{"text":"Un templo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma muralha"},"fr":{"text":"Une muraille"},"en":{"text":"A wall"},"es":{"text":"Una muralla"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-006","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":9,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Depois do dilúvio, que sinal pôs Deus nas nuvens?","bible_ref":"Génesis 9:13","verse_text":"Meu arco porei nas nuvens, o qual será por sinal de aliança entre mim e a terra."},"fr":{"prompt":"Après le déluge, quel signe Dieu a-t-il mis dans la nuée ?","bible_ref":"Genèse 9:13","verse_text":"j’ai placé mon arc dans la nue, et il servira de signe d’alliance entre moi et la terre."},"en":{"prompt":"After the flood, what sign did God set in the clouds?","bible_ref":"Genesis 9:13","verse_text":"I do set my bow in the cloud, and it shall be for a token of a covenant between me and the earth."},"es":{"prompt":"Después del diluvio, ¿qué señal puso Dios en las nubes?","bible_ref":"Génesis 9:13","verse_text":"Mi arco pondré en las nubes, el cual será por señal de convenio entre mí y la tierra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O seu arco"},"fr":{"text":"Son arc"},"en":{"text":"His bow"},"es":{"text":"Su arco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma estrela"},"fr":{"text":"Une étoile"},"en":{"text":"A star"},"es":{"text":"Una estrella"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma pomba"},"fr":{"text":"Une colombe"},"en":{"text":"A dove"},"es":{"text":"Una paloma"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um relâmpago"},"fr":{"text":"Un éclair"},"en":{"text":"Lightning"},"es":{"text":"Un relámpago"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-007","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":21,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Como se chamava o filho que Sara deu a Abraão?","bible_ref":"Génesis 21:3","verse_text":"E chamou Abraão o nome de seu filho que lhe nasceu, que lhe deu à luz Sara, Isaque."},"fr":{"prompt":"Comment s’appelait le fils que Sara a donné à Abraham ?","bible_ref":"Genèse 21:3","verse_text":"Abraham donna le nom d’Isaac au fils qui lui était né, que Sara lui avait enfanté."},"en":{"prompt":"What was the name of the son Sarah bore to Abraham?","bible_ref":"Genesis 21:3","verse_text":"And Abraham called the name of his son that was born unto him, whom Sarah bare to him, Isaac."},"es":{"prompt":"¿Cómo se llamaba el hijo que Sara dio a Abraham?","bible_ref":"Génesis 21:3","verse_text":"Y llamó Abraham el nombre de su hijo que le nació, que le parió Sara, Isaac."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Isaac"},"fr":{"text":"Isaac"},"en":{"text":"Isaac"},"es":{"text":"Isaac"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jacob"},"fr":{"text":"Jacob"},"en":{"text":"Jacob"},"es":{"text":"Jacob"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"José"},"fr":{"text":"Joseph"},"en":{"text":"Joseph"},"es":{"text":"José"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-008","type":"choice","level":"easy","testament":"ot","book":"GEN","chapter":37,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Que presente fez Jacob (Israel) ao seu filho José?","bible_ref":"Génesis 37:3","verse_text":"E amava Israel a José mais que a todos os seus filhos, porque lhe havia tido em sua velhice: e lhe fez uma roupa de diversas cores."},"fr":{"prompt":"Quel cadeau Jacob (Israël) a-t-il fait à son fils Joseph ?","bible_ref":"Genèse 37:3","verse_text":"Israël aimait Joseph plus que tous ses autres fils, parce qu’il l’avait eu dans sa vieillesse; et il lui fit une tunique de plusieurs couleurs."},"en":{"prompt":"What gift did Jacob (Israel) make for his son Joseph?","bible_ref":"Genesis 37:3","verse_text":"Now Israel loved Joseph more than all his children, because he was the son of his old age: and he made him a coat of many colours."},"es":{"prompt":"¿Qué regalo hizo Jacob (Israel) a su hijo José?","bible_ref":"Génesis 37:3","verse_text":"Y amaba Israel á José más que á todos sus hijos, porque le había tenido en su vejez: y le hizo una ropa de diversos colores."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma roupa de muitas cores"},"fr":{"text":"Une tunique de plusieurs couleurs"},"en":{"text":"A coat of many colours"},"es":{"text":"Una túnica de diversos colores"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um anel de ouro"},"fr":{"text":"Un anneau d’or"},"en":{"text":"A gold ring"},"es":{"text":"Un anillo de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma espada"},"fr":{"text":"Une épée"},"en":{"text":"A sword"},"es":{"text":"Una espada"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um cordeiro"},"fr":{"text":"Un agneau"},"en":{"text":"A lamb"},"es":{"text":"Un cordero"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-009","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":2,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Onde pôs a mãe o bebé Moisés para o esconder?","bible_ref":"Êxodo 2:3","verse_text":"Porém não podendo ocultar-lhe mais tempo, tomou uma cesta de juncos, e vedou-a com piche e betume, e colocou nela ao menino, e o pôs entre os juncos à beira do rio:"},"fr":{"prompt":"Où la mère a-t-elle mis le bébé Moïse pour le cacher ?","bible_ref":"Exode 2:3","verse_text":"Ne pouvant plus le cacher, elle prit une caisse de jonc, qu’elle enduisit de bitume et de poix; elle y mit l’enfant, et le déposa parmi les roseaux, sur le bord du fleuve."},"en":{"prompt":"Where did his mother put baby Moses to hide him?","bible_ref":"Exodus 2:3","verse_text":"And when she could not longer hide him, she took for him an ark of bulrushes, and daubed it with slime and with pitch, and put the child therein; and she laid it in the flags by the river’s brink."},"es":{"prompt":"¿Dónde puso la madre al bebé Moisés para esconderlo?","bible_ref":"Éxodo 2:3","verse_text":"Pero no pudiendo ocultarle más tiempo, tomó una arquilla de juncos, y calafateóla con pez y betún, y colocó en ella al niño, y púsolo en un carrizal á la orilla del río:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Numa cesta de juncos, junto ao rio"},"fr":{"text":"Dans une caisse de jonc, au bord du fleuve"},"en":{"text":"In an ark of bulrushes by the river"},"es":{"text":"En una arquilla de juncos, junto al río"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Numa gruta"},"fr":{"text":"Dans une grotte"},"en":{"text":"In a cave"},"es":{"text":"En una cueva"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Num poço"},"fr":{"text":"Dans un puits"},"en":{"text":"In a well"},"es":{"text":"En un pozo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Numa tenda"},"fr":{"text":"Dans une tente"},"en":{"text":"In a tent"},"es":{"text":"En una tienda"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-010","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":3,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Onde viu Moisés uma chama de fogo que não queimava a planta?","bible_ref":"Êxodo 3:2","verse_text":"E apareceu-lhe o anjo do SENHOR em uma chama de fogo em meio de uma sarça: e ele olhou, e viu que a sarça ardia em fogo, e a sarça não se consumia."},"fr":{"prompt":"Où Moïse a-t-il vu une flamme de feu qui ne consumait pas la plante ?","bible_ref":"Exode 3:2","verse_text":"L’ange de l’Éternel lui apparut dans une flamme de feu, au milieu d’un buisson. Moïse regarda; et voici, le buisson était tout en feu, et le buisson ne se consumait point."},"en":{"prompt":"Where did Moses see a flame of fire that did not burn up the plant?","bible_ref":"Exodus 3:2","verse_text":"And the angel of the LORD appeared unto him in a flame of fire out of the midst of a bush: and he looked, and, behold, the bush burned with fire, and the bush was not consumed."},"es":{"prompt":"¿Dónde vio Moisés una llama de fuego que no consumía la planta?","bible_ref":"Éxodo 3:2","verse_text":"Y apareciósele el Angel de Jehová en una llama de fuego en medio de una zarza: y él miró, y vió que la zarza ardía en fuego, y la zarza no se consumía."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Numa sarça"},"fr":{"text":"Dans un buisson"},"en":{"text":"In a bush"},"es":{"text":"En una zarza"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Numa oliveira"},"fr":{"text":"Dans un olivier"},"en":{"text":"In an olive tree"},"es":{"text":"En un olivo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Numa videira"},"fr":{"text":"Dans une vigne"},"en":{"text":"In a vine"},"es":{"text":"En una vid"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Numa figueira"},"fr":{"text":"Dans un figuier"},"en":{"text":"In a fig tree"},"es":{"text":"En una higuera"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-easy-011","type":"choice","level":"easy","testament":"ot","book":"EXO","chapter":16,"verse_start":31,"verse_end":31,"texts":{"pt":{"prompt":"Que nome deu o povo de Israel ao pão que vinha do céu?","bible_ref":"Êxodo 16:31","verse_text":"E a casa de Israel o chamou maná; e era como semente de coentro, branco, e seu sabor como de bolos com mel."},"fr":{"prompt":"Quel nom le peuple d’Israël a-t-il donné au pain venu du ciel ?","bible_ref":"Exode 16:31","verse_text":"La maison d’Israël donna à cette nourriture le nom de manne. Elle ressemblait à de la graine de coriandre; elle était blanche, et avait le goût d’un gâteau au miel."},"en":{"prompt":"What did the people of Israel call the bread from heaven?","bible_ref":"Exodus 16:31","verse_text":"And the house of Israel called the name thereof Manna: and it was like coriander seed, white; and the taste of it was like wafers made with honey."},"es":{"prompt":"¿Qué nombre dio el pueblo de Israel al pan que venía del cielo?","bible_ref":"Éxodo 16:31","verse_text":"Y la casa de Israel lo llamó Maná; y era como simiente de culantro, blanco, y su sabor como de hojuelas con miel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Maná"},"fr":{"text":"Manne"},"en":{"text":"Manna"},"es":{"text":"Maná"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Mel"},"fr":{"text":"Miel"},"en":{"text":"Honey"},"es":{"text":"Miel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Trigo"},"fr":{"text":"Blé"},"en":{"text":"Wheat"},"es":{"text":"Trigo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Codorniz"},"fr":{"text":"Caille"},"en":{"text":"Quail"},"es":{"text":"Codorniz"}}}]}$json$::jsonb);
