select public.upsert_bank_question($json${"id":"pent-medium-001","type":"choice","level":"medium","testament":"ot","book":"GEN","chapter":8,"verse_start":7,"verse_end":8,"texts":{"pt":{"prompt":"Que ave enviou Noé da arca antes da pomba?","bible_ref":"Génesis 8:7-8","verse_text":"E enviou ao corvo, o qual saiu, e esteve indo e voltando até que as águas se secaram de sobre a terra. Enviou também de si à pomba, para ver se as águas se haviam retirado de sobre a face da terra;"},"fr":{"prompt":"Quel oiseau Noé a-t-il lâché de l’arche avant la colombe ?","bible_ref":"Genèse 8:7-8","verse_text":"Il lâcha le corbeau, qui sortit, partant et revenant, jusqu’à ce que les eaux eussent séché sur la terre. Il lâcha aussi la colombe, pour voir si les eaux avaient diminué à la surface de la terre."},"en":{"prompt":"Which bird did Noah send out of the ark before the dove?","bible_ref":"Genesis 8:7-8","verse_text":"And he sent forth a raven, which went forth to and fro, until the waters were dried up from off the earth. Also he sent forth a dove from him, to see if the waters were abated from off the face of the ground;"},"es":{"prompt":"¿Qué ave envió Noé desde el arca antes de la paloma?","bible_ref":"Génesis 8:7-8","verse_text":"Y envió al cuervo, el cual salió, y estuvo yendo y tornando hasta que las aguas se secaron de sobre la tierra. Envió también de sí á la paloma, para ver si las aguas se habían retirado de sobre la faz de la tierra;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O corvo"},"fr":{"text":"Le corbeau"},"en":{"text":"A raven"},"es":{"text":"El cuervo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A águia"},"fr":{"text":"L’aigle"},"en":{"text":"An eagle"},"es":{"text":"El águila"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O pardal"},"fr":{"text":"Le moineau"},"en":{"text":"A sparrow"},"es":{"text":"El gorrión"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A andorinha"},"fr":{"text":"L’hirondelle"},"en":{"text":"A swallow"},"es":{"text":"La golondrina"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-002","type":"choice","level":"medium","testament":"ot","book":"GEN","chapter":8,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"O que trazia a pomba no bico quando voltou à arca ao fim da tarde?","bible_ref":"Génesis 8:11","verse_text":"E a pomba voltou a ele à hora da tarde; e eis que trazia uma folha de oliveira tomada em seu bico; então Noé entendeu que as águas haviam se retirado de sobre a terra."},"fr":{"prompt":"Que rapportait la colombe dans son bec quand elle est revenue à l’arche le soir ?","bible_ref":"Genèse 8:11","verse_text":"La colombe revint à lui sur le soir; et voici, une feuille d’olivier arrachée était dans son bec. Noé connut ainsi que les eaux avaient diminué sur la terre."},"en":{"prompt":"What did the dove bring in her mouth when she came back to the ark in the evening?","bible_ref":"Genesis 8:11","verse_text":"And the dove came in to him in the evening; and, lo, in her mouth was an olive leaf pluckt off: so Noah knew that the waters were abated from off the earth."},"es":{"prompt":"¿Qué traía la paloma en el pico cuando volvió al arca a la tarde?","bible_ref":"Génesis 8:11","verse_text":"Y la paloma volvió á él á la hora de la tarde; y he aquí que traía una hoja de oliva tomada en su pico: y entendió Noé que las aguas se habían retirado de sobre la tierra."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma folha de oliveira"},"fr":{"text":"Une feuille d’olivier"},"en":{"text":"An olive leaf"},"es":{"text":"Una hoja de olivo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma espiga de trigo"},"fr":{"text":"Un épi de blé"},"en":{"text":"An ear of wheat"},"es":{"text":"Una espiga de trigo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um figo"},"fr":{"text":"Une figue"},"en":{"text":"A fig"},"es":{"text":"Un higo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um cacho de uvas"},"fr":{"text":"Une grappe de raisin"},"e