select public.upsert_bank_question($json${"id":"pent-medium-003","type":"choice","level":"medium","testament":"ot","book":"GEN","chapter":19,"verse_start":24,"verse_end":24,"texts":{"pt":{"prompt":"O que fez o SENHOR chover sobre Sodoma e Gomorra?","bible_ref":"Génesis 19:24","verse_text":"Então choveu o SENHOR sobre Sodoma e sobre Gomorra enxofre e fogo da parte do SENHOR desde os céus;"},"fr":{"prompt":"Que fit pleuvoir l’Éternel sur Sodome et Gomorrhe ?","bible_ref":"Genèse 19:24","verse_text":"Alors l’Éternel fit pleuvoir du ciel sur Sodome et sur Gomorrhe du soufre et du feu, de par l’Éternel."},"en":{"prompt":"What did the LORD rain upon Sodom and Gomorrah?","bible_ref":"Genesis 19:24","verse_text":"Then the LORD rained upon Sodom and upon Gomorrah brimstone and fire from the LORD out of heaven;"},"es":{"prompt":"¿Qué hizo llover Jehová sobre Sodoma y Gomorra?","bible_ref":"Génesis 19:24","verse_text":"Entonces llovió Jehová sobre Sodoma y sobre Gomorra azufre y fuego de parte de Jehová desde los cielos;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Enxofre e fogo"},"fr":{"text":"Du soufre et du feu"},"en":{"text":"Brimstone and fire"},"es":{"text":"Azufre y fuego"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pedras e cinza"},"fr":{"text":"Des pierres et de la cendre"},"en":{"text":"Stones and ashes"},"es":{"text":"Piedras y ceniza"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Água e sal"},"fr":{"text":"De l’eau et du sel"},"en":{"text":"Water and salt"},"es":{"text":"Agua y sal"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Granizo e neve"},"fr":{"text":"De la grêle et de la neige"},"en":{"text":"Hail and snow"},"es":{"text":"Granizo y nieve"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-004","type":"choice","level":"medium","testament":"ot","book":"GEN","chapter":22,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Para que terra mandou Deus Abraão ir, para lá oferecer Isaac?","bible_ref":"Génesis 22:2","verse_text":"E disse: Toma agora teu filho, teu único, Isaque, a quem amas, e vai à terra de Moriá, e oferece-o ali em holocausto sobre um dos montes que eu te direi."},"fr":{"prompt":"Dans quel pays Dieu envoya-t-il Abraham pour y offrir Isaac ?","bible_ref":"Genèse 22:2","verse_text":"Dieu dit: Prends ton fils, ton unique, celui que tu aimes, Isaac; va-t’en au pays de Morija, et là offre-le en holocauste sur l’une des montagnes que je te dirai."},"en":{"prompt":"To which land did God send Abraham to offer Isaac there?","bible_ref":"Genesis 22:2","verse_text":"And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of."},"es":{"prompt":"¿A qué tierra mandó Dios ir a Abraham para ofrecer allí a Isaac?","bible_ref":"Génesis 22:2","verse_text":"Y dijo: Toma ahora tu hijo, tu único, Isaac, á quien amas, y vete á tierra de Moriah, y ofrécelo allí en holocausto sobre uno de los montes que yo te diré."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Moriá"},"fr":{"text":"Morija"},"en":{"text":"Moriah"},"es":{"text":"Moriah"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Egito"},"fr":{"text":"Égypte"},"en":{"text":"Egypt"},"es":{"text":"Egipto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Midiã"},"fr":{"text":"Madian"},"en":{"text":"Midian"},"es":{"text":"Madián"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Moabe"},"fr":{"text":"Moab"},"en":{"text":"Moab"},"es":{"text":"Moab"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-005","type":"choice","level":"medium","testament":"ot","book":"GEN","chapter":25,"verse_start":33,"verse_end":34,"texts":{"pt":{"prompt":"Que comida deu Jacob a Esaú em troca do direito de primogenitura?","bible_ref":"Génesis 25:33-34","verse_text":"E disse Jacó: Jura-me hoje. E ele lhe jurou, e vendeu a Jacó sua primogenitura. Então Jacó deu a Esaú pão e do guisado das lentilhas; e ele comeu e bebeu, e levantou-se, e foi-se. Assim menosprezou Esaú a primogenitura."},"fr":{"prompt":"Quel plat Jacob a-t-il donné à Ésaü en échange de son droit d’aînesse ?","bible_ref":"Genèse 25:33-34","verse_text":"Et Jacob dit: Jure-le moi d’abord. Il le lui jura, et il vendit son droit d’aînesse à Jacob. Alors Jacob donna à Ésaü du pain et du potage de lentilles. Il mangea et but, puis se leva et s’en alla. C’est ainsi qu’Ésaü méprisa le droit d’aînesse."},"en":{"prompt":"What food did Jacob give Esau in exchange for his birthright?","bible_ref":"Genesis 25:33-34","verse_text":"And Jacob said, Swear to me this day; and he sware unto him: and he sold his birthright unto Jacob. Then Jacob gave Esau bread and pottage of lentiles; and he did eat and drink, and rose up, and went his way: thus Esau despised his birthright."},"es":{"prompt":"¿Qué comida dio Jacob a Esaú a cambio de su primogenitura?","bible_ref":"Génesis 25:33-34","verse_text":"Y dijo Jacob: Júramelo en este día. Y él le juró, y vendió á Jacob su primogenitura. Entonces Jacob dió á Esaú pan y del guisado de las lentejas; y él comió y bebió, y levantóse, y fuése. Así menospreció Esaú la primogenitura."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Pão e guisado de lentilhas"},"fr":{"text":"Du pain et un potage de lentilles"},"en":{"text":"Bread and lentil stew"},"es":{"text":"Pan y guisado de lentejas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Carne de veado"},"fr":{"text":"Du gibier"},"en":{"text":"Venison"},"es":{"text":"Carne de venado"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Peixe assado"},"fr":{"text":"Du poisson grillé"},"en":{"text":"Roasted fish"},"es":{"text":"Pescado asado"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Figos e mel"},"fr":{"text":"Des figues et du miel"},"en":{"text":"Figs and honey"},"es":{"text":"Higos y miel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-006","type":"choice","level":"medium","testament":"ot","book":"GEN","chapter":41,"verse_start":30,"verse_end":30,"texts":{"pt":{"prompt":"Quantos anos de fome anunciou José ao Faraó?","bible_ref":"Génesis 41:30","verse_text":"E se levantarão depois eles sete anos de fome; e toda a fartura será esquecida na terra do Egito; e a fome consumirá a terra;"},"fr":{"prompt":"Combien d’années de famine Joseph a-t-il annoncées au pharaon ?","bible_ref":"Genèse 41:30","verse_text":"Sept années de famine viendront après elles; et l’on oubliera toute cette abondance au pays d’Égypte, et la famine consumera le pays."},"en":{"prompt":"How many years of famine did Joseph announce to Pharaoh?","bible_ref":"Genesis 41:30","verse_text":"And there shall arise after them seven years of famine; and all the plenty shall be forgotten in the land of Egypt; and the famine shall consume the land;"},"es":{"prompt":"¿Cuántos años de hambre anunció José a Faraón?","bible_ref":"Génesis 41:30","verse_text":"Y levantarse han tras ellos siete años de hambre; y toda la hartura será olvidada en la tierra de Egipto; y el hambre consumirá la tierra;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"7"},"fr":{"text":"7"},"en":{"text":"7"},"es":{"text":"7"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"3"},"fr":{"text":"3"},"en":{"text":"3"},"es":{"text":"3"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"10"},"fr":{"text":"10"},"en":{"text":"10"},"es":{"text":"10"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"40"},"fr":{"text":"40"},"en":{"text":"40"},"es":{"text":"40"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-007","type":"choice","level":"medium","testament":"ot","book":"EXO","chapter":17,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Em Horebe, o que mandou Deus Moisés fazer para o povo ter água?","bible_ref":"Êxodo 17:6","verse_text":"Eis que eu estou diante de ti ali sobre a rocha em Horebe; e ferirás a rocha, e sairão dela águas, e beberá o povo. E Moisés o fez assim em presença dos anciãos de Israel."},"fr":{"prompt":"À Horeb, que Dieu ordonna-t-il à Moïse de faire pour que le peuple ait de l’eau ?","bible_ref":"Exode 17:6","verse_text":"Voici, je me tiendrai devant toi sur le rocher d’Horeb; tu frapperas le rocher, et il en sortira de l’eau, et le peuple boira. Et Moïse fit ainsi, aux yeux des anciens d’Israël."},"en":{"prompt":"At Horeb, what did God tell Moses to do so the people could have water?","bible_ref":"Exodus 17:6","verse_text":"Behold, I will stand before thee there upon the rock in Horeb; and thou shalt smite the rock, and there shall come water out of it, that the people may drink. And Moses did so in the sight of the elders of Israel."},"es":{"prompt":"En Horeb, ¿qué mandó Dios hacer a Moisés para que el pueblo tuviera agua?","bible_ref":"Éxodo 17:6","verse_text":"He aquí que yo estoy delante de ti allí sobre la peña en Horeb; y herirás la peña, y saldrán de ella aguas, y beberá el pueblo. Y Moisés lo hizo así en presencia de los ancianos de Israel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ferir a rocha"},"fr":{"text":"Frapper le rocher"},"en":{"text":"Smite the rock"},"es":{"text":"Herir la peña"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cavar um poço"},"fr":{"text":"Creuser un puits"},"en":{"text":"Dig a well"},"es":{"text":"Cavar un pozo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Orar toda a noite"},"fr":{"text":"Prier toute la nuit"},"en":{"text":"Pray all night"},"es":{"text":"Orar toda la noche"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Lançar sal na fonte"},"fr":{"text":"Jeter du sel dans la source"},"en":{"text":"Throw salt into the spring"},"es":{"text":"Echar sal en la fuente"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-008","type":"choice","level":"medium","testament":"ot","book":"EXO","chapter":12,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Na Páscoa, onde punham os israelitas o sangue do cordeiro?","bible_ref":"Êxodo 12:7","verse_text":"E tomarão do sangue, e o porão nos dois postes e na verga das casas em que o comerão."},"fr":{"prompt":"À la Pâque, où les Israélites mettaient-ils le sang de l’agneau ?","bible_ref":"Exode 12:7","verse_text":"On prendra de son sang, et on en mettra sur les deux poteaux et sur le linteau de la porte des maisons où on le mangera."},"en":{"prompt":"At the Passover, where did the Israelites put the lamb’s blood?","bible_ref":"Exodus 12:7","verse_text":"And they shall take of the blood, and strike it on the two side posts and on the upper door post of the houses, wherein they shall eat it."},"es":{"prompt":"En la Pascua, ¿dónde ponían los israelitas la sangre del cordero?","bible_ref":"Éxodo 12:7","verse_text":"Y tomarán de la sangre, y pondrán en los dos postes y en el dintel de las casas en que lo han de comer."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nos postes e na verga das portas"},"fr":{"text":"Sur les poteaux et le linteau de la porte"},"en":{"text":"On the side posts and upper door post"},"es":{"text":"En los postes y el dintel de las casas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No altar do templo"},"fr":{"text":"Sur l’autel du temple"},"en":{"text":"On the temple altar"},"es":{"text":"En el altar del templo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Nas próprias roupas"},"fr":{"text":"Sur leurs vêtements"},"en":{"text":"On their own clothes"},"es":{"text":"En sus propias ropas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No telhado das casas"},"fr":{"text":"Sur le toit des maisons"},"en":{"text":"On the roofs of the houses"},"es":{"text":"En el techo de las casas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-009","type":"choice","level":"medium","testament":"ot","book":"EXO","chapter":32,"verse_start":35,"verse_end":35,"texts":{"pt":{"prompt":"Quem fez o bezerro de ouro no deserto?","bible_ref":"Êxodo 32:35","verse_text":"E o SENHOR feriu ao povo, porque fizeram o bezerro que formou Arão."},"fr":{"prompt":"Qui a fait le veau d’or dans le désert ?","bible_ref":"Exode 32:35","verse_text":"L’Éternel frappa le peuple, parce qu’il avait fait le veau, fabriqué par Aaron."},"en":{"prompt":"Who made the golden calf in the wilderness?","bible_ref":"Exodus 32:35","verse_text":"And the LORD plagued the people, because they made the calf, which Aaron made."},"es":{"prompt":"¿Quién hizo el becerro de oro en el desierto?","bible_ref":"Éxodo 32:35","verse_text":"Y Jehová hirió al pueblo, porque habían hecho el becerro que formó Aarón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Arão"},"fr":{"text":"Aaron"},"en":{"text":"Aaron"},"es":{"text":"Aarón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Josué"},"fr":{"text":"Josué"},"en":{"text":"Joshua"},"es":{"text":"Josué"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Coré"},"fr":{"text":"Koré"},"en":{"text":"Korah"},"es":{"text":"Coré"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-010","type":"choice","level":"medium","testament":"ot","book":"LEV","chapter":16,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Em Levítico 16, que animal levava sobre si as iniquidades do povo para o deserto?","bible_ref":"Levítico 16:22","verse_text":"E aquele bode macho levará sobre si todas as iniquidades deles à terra inabitada: e deixará ir o bode macho pelo deserto."},"fr":{"prompt":"En Lévitique 16, quel animal emportait les iniquités du peuple dans le désert ?","bible_ref":"Lévitique 16:22","verse_text":"Le bouc emportera sur lui toutes leurs iniquités dans une terre désolée; il sera chassé dans le désert."},"en":{"prompt":"In Leviticus 16, which animal bore the iniquities of the people into the wilderness?","bible_ref":"Leviticus 16:22","verse_text":"And the goat shall bear upon him all their iniquities unto a land not inhabited: and he shall let go the goat in the wilderness."},"es":{"prompt":"En Levítico 16, ¿qué animal llevaba sobre sí las iniquidades del pueblo al desierto?","bible_ref":"Levítico 16:22","verse_text":"Y aquel macho cabrío llevará sobre sí todas las iniquidades de ellos á tierra inhabitada: y dejará ir el macho cabrío por el desierto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um bode"},"fr":{"text":"Un bouc"},"en":{"text":"A goat"},"es":{"text":"Un macho cabrío"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um cordeiro"},"fr":{"text":"Un agneau"},"en":{"text":"A lamb"},"es":{"text":"Un cordero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um touro"},"fr":{"text":"Un taureau"},"en":{"text":"A bull"},"es":{"text":"Un toro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma pomba"},"fr":{"text":"Une colombe"},"en":{"text":"A dove"},"es":{"text":"Una paloma"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-011","type":"choice","level":"medium","testament":"ot","book":"NUM","chapter":21,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"O que fez Moisés para que quem fosse mordido por serpentes vivesse?","bible_ref":"Números 21:9","verse_text":"E Moisés fez uma serpente de bronze, e a pôs sobre a haste, e foi, que quando alguma serpente mordia a algum, olhava à serpente de bronze, e vivia."},"fr":{"prompt":"Qu’a fait Moïse pour que ceux qui étaient mordus par les serpents vivent ?","bible_ref":"Nombres 21:9","verse_text":"Moïse fit un serpent d’airain, et le plaça sur une perche; et quiconque avait été mordu par un serpent, et regardait le serpent d’airain, conservait la vie."},"en":{"prompt":"What did Moses make so that those bitten by serpents would live?","bible_ref":"Numbers 21:9","verse_text":"And Moses made a serpent of brass, and put it upon a pole, and it came to pass, that if a serpent had bitten any man, when he beheld the serpent of brass, he lived."},"es":{"prompt":"¿Qué hizo Moisés para que los mordidos por serpientes vivieran?","bible_ref":"Números 21:9","verse_text":"Y Moisés hizo una serpiente de metal, y púsola sobre la bandera: y fué, que cuando alguna serpiente mordía á alguno, miraba á la serpiente de metal, y vivía."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma serpente de bronze numa haste"},"fr":{"text":"Un serpent d’airain sur une perche"},"en":{"text":"A serpent of brass on a pole"},"es":{"text":"Una serpiente de metal sobre un asta"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um altar de pedra"},"fr":{"text":"Un autel de pierre"},"en":{"text":"A stone altar"},"es":{"text":"Un altar de piedra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um poço de água"},"fr":{"text":"Un puits d’eau"},"en":{"text":"A well of water"},"es":{"text":"Un pozo de agua"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um bezerro de ouro"},"fr":{"text":"Un veau d’or"},"en":{"text":"A golden calf"},"es":{"text":"Un becerro de oro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-medium-012","type":"choice","level":"medium","testament":"ot","book":"DEU","chapter":34,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"De que monte viu Moisés a terra prometida antes de morrer?","bible_ref":"Deuteronómio 34:1","verse_text":"E Moisés subiu dos campos de Moabe ao monte Nebo, ao cume de Pisga, que está em frente de Jericó; e o SENHOR mostrou-lhe toda a terra de Gileade até Dã,"},"fr":{"prompt":"De quelle montagne Moïse a-t-il vu la terre promise avant de mourir ?","bible_ref":"Deutéronome 34:1","verse_text":"Moïse monta des plaines de Moab sur le mont Nebo, au sommet du Pisga, vis-à-vis de Jéricho. Et l’Éternel lui fit voir tout le pays:"},"en":{"prompt":"From which mountain did Moses see the promised land before he died?","bible_ref":"Deuteronomy 34:1","verse_text":"And Moses went up from the plains of Moab unto the mountain of Nebo, to the top of Pisgah, that is over against Jericho. And the LORD shewed him all the land of Gilead, unto Dan,"},"es":{"prompt":"¿Desde qué monte vio Moisés la tierra prometida antes de morir?","bible_ref":"Deuteronomio 34:1","verse_text":"Y subió Moisés de los campos de Moab al monte de Nebo, á la cumbre de Pisga, que está enfrente de Jericó: y mostróle Jehová toda la tierra de Galaad hasta Dan,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nebo"},"fr":{"text":"Nebo"},"en":{"text":"Nebo"},"es":{"text":"Nebo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sinai"},"fr":{"text":"Sinaï"},"en":{"text":"Sinai"},"es":{"text":"Sinaí"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Carmelo"},"fr":{"text":"Carmel"},"en":{"text":"Carmel"},"es":{"text":"Carmelo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ararate"},"fr":{"text":"Ararat"},"en":{"text":"Ararat"},"es":{"text":"Ararat"}}}]}$json$::jsonb);
