select public.upsert_bank_question($json${"id":"pent-medium-020","type":"verse","level":"medium","testament":"ot","book":"DEU","chapter":8,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"E te afligiu, e te fez ter fome, e te sustentou com maná, comida que não conhecias tu, nem teus pais a conheciam; para fazer-te saber que o homem não viverá de só _____, mas de tudo o que sai da boca do SENHOR viverá o homem.","bible_ref":"Deuteronómio 8:3","verse_text":"E te afligiu, e te fez ter fome, e te sustentou com maná, comida que não conhecias tu, nem teus pais a conheciam; para fazer-te saber que o homem não viverá de só pão, mas de tudo o que sai da boca do SENHOR viverá o homem."},"fr":{"prompt":"Il t’a humilié, il t’a fait souffrir de la faim, et il t’a nourri de la manne, que tu ne connaissais pas et que n’avaient pas connue tes pères, afin de t’apprendre que l’homme ne vit pas de _____ seulement, mais que l’homme vit de tout ce qui sort de la bouche de l’Éternel.","bible_ref":"Deutéronome 8:3","verse_text":"Il t’a humilié, il t’a fait souffrir de la faim, et il t’a nourri de la manne, que tu ne connaissais pas et que n’avaient pas connue tes pères, afin de t’apprendre que l’homme ne vit pas de pain seulement, mais que l’homme vit de tout ce qui sort de la bouche de l’Éternel."},"en":{"prompt":"And he humbled thee, and suffered thee to hunger, and fed thee with manna, which thou knewest not, neither did thy fathers know; that he might make thee know that man doth not live by _____ only, but by every word that proceedeth out of the mouth of the LORD doth man live.","bible_ref":"Deuteronomy 8:3","verse_text":"And he humbled thee, and suffered thee to hunger, and fed thee with manna, which thou knewest not, neither did thy fathers know; that he might make thee know that man doth not live by bread only, but by every word that proceedeth out of the mouth of the LORD doth man live."},"es":{"prompt":"Y te afligió, é hízote tener hambre, y te sustentó con maná, comida que no conocías tú, ni tus padres la habían conocido; para hacerte saber que el hombre no vivirá de solo _____, mas de todo lo que sale de la boca de Jehová vivirá el hombre.","bible_ref":"Deuteronomio 8:3","verse_text":"Y te afligió, é hízote tener hambre, y te sustentó con maná, comida que no conocías tú, ni tus padres la habían conocido; para hacerte saber que el hombre no vivirá de solo pan, mas de todo lo que sale de la boca de Jehová vivirá el hombre."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"água"},"fr":{"text":"eau"},"en":{"text":"water"},"es":{"text":"agua"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"vinho"},"fr":{"text":"vin"},"en":{"text":"wine"},"es":{"text":"vino"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"carne"},"fr":{"text":"viande"},"en":{"text":"meat"},"es":{"text":"carne"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"pão"},"fr":{"text":"pain"},"en":{"text":"bread"},"es":{"text":"pan"}}}]}$json$::jsonb);
