select public.upsert_bank_question($json${"id":"pent-hard-003","type":"choice","level":"hard","testament":"ot","book":"GEN","chapter":29,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Como se chamava a filha mais velha de Labão?","bible_ref":"Génesis 29:16","verse_text":"E Labão tinha duas filhas: o nome da mais velha era Lia, e o nome da mais nova, Raquel."},"fr":{"prompt":"Comment s’appelait la fille aînée de Laban ?","bible_ref":"Genèse 29:16","verse_text":"Or, Laban avait deux filles: l’aînée s’appelait Léa, et la cadette Rachel."},"en":{"prompt":"What was the name of Laban’s elder daughter?","bible_ref":"Genesis 29:16","verse_text":"And Laban had two daughters: the name of the elder was Leah, and the name of the younger was Rachel."},"es":{"prompt":"¿Cómo se llamaba la hija mayor de Labán?","bible_ref":"Génesis 29:16","verse_text":"Y Labán tenía dos hijas: el nombre de la mayor era Lea, y el nombre de la menor, Rachêl."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Lia"},"fr":{"text":"Léa"},"en":{"text":"Leah"},"es":{"text":"Lea"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Raquel"},"fr":{"text":"Rachel"},"en":{"text":"Rachel"},"es":{"text":"Rachêl"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Diná"},"fr":{"text":"Dina"},"en":{"text":"Dinah"},"es":{"text":"Dina"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Rebeca"},"fr":{"text":"Rebecca"},"en":{"text":"Rebekah"},"es":{"text":"Rebeca"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-hard-004","type":"choice","level":"hard","testament":"ot","book":"GEN","chapter":41,"verse_start":45,"verse_end":45,"texts":{"pt":{"prompt":"Como se chamava a mulher que o Faraó deu a José?","bible_ref":"Génesis 41:45","verse_text":"E chamou Faraó o nome de José, Zefenate-Paneia; e deu-lhe por mulher a Azenate, filha de Potífera, sacerdote de Om. E saiu José por toda a terra do Egito."},"fr":{"prompt":"Comment s’appelait la femme que le pharaon donna à Joseph ?","bible_ref":"Genèse 41:45","verse_text":"Pharaon appela Joseph du nom de Tsaphnath-Paenéach; et il lui donna pour femme Asnath, fille de Poti-Phéra, prêtre d’On. Et Joseph partit pour visiter le pays d’Égypte."},"en":{"prompt":"What was the name of the wife Pharaoh gave to Joseph?","bible_ref":"Genesis 41:45","verse_text":"And Pharaoh called Joseph’s name Zaphnath-paaneah; and he gave him to wife Asenath the daughter of Poti-pherah priest of On. And Joseph went out over all the land of Egypt."},"es":{"prompt":"¿Cómo se llamaba la mujer que Faraón dio a José?","bible_ref":"Génesis 41:45","verse_text":"Y llamó Faraón el nombre de José, Zaphnath-paaneah; y dióle por mujer á Asenath, hija de Potipherah, sacerdote de On. Y salió José por toda la tierra de Egipto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Azenate"},"fr":{"text":"Asnath"},"en":{"text":"Asenath"},"es":{"text":"Asenath"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Zípora"},"fr":{"text":"Séphora"},"en":{"text":"Zipporah"},"es":{"text":"Séphora"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Agar"},"fr":{"text":"Agar"},"en":{"text":"Hagar"},"es":{"text":"Agar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tamar"},"fr":{"text":"Tamar"},"en":{"text":"Tamar"},"es":{"text":"Thamar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-hard-005","type":"choice","level":"hard","testament":"ot","book":"EXO","chapter":2,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Que nome deu Moisés ao filho que lhe nasceu em Midiã, por ser peregrino em terra alheia?","bible_ref":"Êxodo 2:22","verse_text":"A qual lhe deu à luz um filho, e ele lhe pôs por nome Gérson: porque disse: Peregrino sou em terra alheia."},"fr":{"prompt":"Quel nom Moïse donna-t-il au fils né en Madian, parce qu’il était un étranger dans un pays étranger ?","bible_ref":"Exode 2:22","verse_text":"Elle enfanta un fils, qu’il appela du nom de Guerschom, car, dit-il, j’habite un pays étranger."},"en":{"prompt":"What name did Moses give the son born in Midian, because he was a stranger in a strange land?","bible_ref":"Exodus 2:22","verse_text":"And she bare him a son, and he called his name Gershom: for he said, I have been a stranger in a strange land."},"es":{"prompt":"¿Qué nombre dio Moisés al hijo nacido en Madián, por ser extranjero en tierra ajena?","bible_ref":"Éxodo 2:22","verse_text":"La cual le parió un hijo, y él le puso por nombre Gersom: porque dijo: Peregrino soy en tierra ajena."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Gérson"},"fr":{"text":"Guerschom"},"en":{"text":"Gershom"},"es":{"text":"Gersom"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nadabe"},"fr":{"text":"Nadab"},"en":{"text":"Nadab"},"es":{"text":"Nadab"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Eleazar"},"fr":{"text":"Éléazar"},"en":{"text":"Eleazar"},"es":{"text":"Eleazar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fineias"},"fr":{"text":"Phinées"},"en":{"text":"Phinehas"},"es":{"text":"Phinees"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-hard-006","type":"choice","level":"hard","testament":"ot","book":"EXO","chapter":17,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Quem sustentou as mãos de Moisés até ao pôr do sol?","bible_ref":"Êxodo 17:12","verse_text":"E as mãos de Moisés estavam pesadas; pelo que tomaram uma pedra, e puseram-na debaixo dele, e se sentou sobre ela; e Arão e Hur sustentavam suas mãos, o um de uma parte e o outro de outra; assim houve em suas mãos firmeza até que se pôs o sol."},"fr":{"prompt":"Qui soutint les mains de Moïse jusqu’au coucher du soleil ?","bible_ref":"Exode 17:12","verse_text":"Les mains de Moïse étant fatiguées, ils prirent une pierre qu’ils placèrent sous lui, et il s’assit dessus. Aaron et Hur soutenaient ses mains, l’un d’un côté, l’autre de l’autre; et ses mains restèrent fermes jusqu’au coucher du soleil."},"en":{"prompt":"Who held up Moses’ hands until the going down of the sun?","bible_ref":"Exodus 17:12","verse_text":"But Moses’ hands were heavy; and they took a stone, and put it under him, and he sat thereon; and Aaron and Hur stayed up his hands, the one on the one side, and the other on the other side; and his hands were steady until the going down of the sun."},"es":{"prompt":"¿Quiénes sostuvieron las manos de Moisés hasta la puesta del sol?","bible_ref":"Éxodo 17:12","verse_text":"Y las manos de Moisés estaban pesadas; por lo que tomaron una piedra, y pusiéronla debajo de él, y se sentó sobre ella: y Aarón y Hur sustentaban sus manos, el uno de una parte y el otro de otra; así hubo en sus manos firmeza hasta que se puso el sol."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Arão e Hur"},"fr":{"text":"Aaron et Hur"},"en":{"text":"Aaron and Hur"},"es":{"text":"Aarón y Hur"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Josué e Calebe"},"fr":{"text":"Josué et Caleb"},"en":{"text":"Joshua and Caleb"},"es":{"text":"Josué y Caleb"}}},{"position":3,"is_correct":