select public.upsert_bank_question($json${"id":"pent-hard-007","type":"choice","level":"hard","testament":"ot","book":"EXO","chapter":31,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Quem foi chamado por nome, filho de Uri, da tribo de Judá, para fazer as obras do tabernáculo?","bible_ref":"Êxodo 31:2","verse_text":"Olha, eu chamei por seu nome a Bezalel, filho de Uri, filho de Hur, da tribo de Judá;"},"fr":{"prompt":"Qui fut appelé par son nom, fils d’Uri, de la tribu de Juda, pour faire les ouvrages du tabernacle ?","bible_ref":"Exode 31:2","verse_text":"Sache que j’ai choisi Betsaleel, fils d’Uri, fils de Hur, de la tribu de Juda."},"en":{"prompt":"Who was called by name, the son of Uri, of the tribe of Judah, to make the works of the tabernacle?","bible_ref":"Exodus 31:2","verse_text":"See, I have called by name Bezaleel the son of Uri, the son of Hur, of the tribe of Judah:"},"es":{"prompt":"¿Quién fue llamado por su nombre, hijo de Uri, de la tribu de Judá, para hacer las obras del tabernáculo?","bible_ref":"Éxodo 31:2","verse_text":"Mira, yo he llamado por su nombre á Bezaleel, hijo de Uri, hijo de Hur, de la tribu de Judá;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Bezalel"},"fr":{"text":"Betsaleel"},"en":{"text":"Bezaleel"},"es":{"text":"Bezaleel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Coré"},"fr":{"text":"Koré"},"en":{"text":"Korah"},"es":{"text":"Coré"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Eleazar"},"fr":{"text":"Éléazar"},"en":{"text":"Eleazar"},"es":{"text":"Eleazar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-hard-008","type":"choice","level":"hard","testament":"ot","book":"LEV","chapter":10,"verse_start":1,"verse_end":2,"texts":{"pt":{"prompt":"Que filhos de Arão ofereceram fogo estranho diante do SENHOR e morreram?","bible_ref":"Levítico 10:1-2","verse_text":"E os filhos de Arão, Nadabe e Abiú, tomaram cada um seu incensário, e puseram fogo neles, sobre o qual puseram incenso, e ofereceram diante do SENHOR fogo estranho, que ele nunca lhes mandou. E saiu fogo de diante do SENHOR que os queimou, e morreram diante do SENHOR."},"fr":{"prompt":"Quels fils d’Aaron offrirent devant l’Éternel un feu étranger et moururent ?","bible_ref":"Lévitique 10:1-2","verse_text":"Les fils d’Aaron, Nadab et Abihu, prirent chacun un brasier, y mirent du feu, et posèrent du parfum dessus; ils apportèrent devant l’Éternel du feu étranger, ce qu’il ne leur avait point ordonné. Alors le feu sortit de devant l’Éternel, et les consuma: ils moururent devant l’Éternel."},"en":{"prompt":"Which sons of Aaron offered strange fire before the LORD and died?","bible_ref":"Leviticus 10:1-2","verse_text":"And Nadab and Abihu, the sons of Aaron, took either of them his censer, and put fire therein, and put incense thereon, and offered strange fire before the LORD, which he commanded them not. And there went out fire from the LORD, and devoured them, and they died before the LORD."},"es":{"prompt":"¿Qué hijos de Aarón ofrecieron fuego extraño delante de Jehová y murieron?","bible_ref":"Levítico 10:1-2","verse_text":"Y los hijos de Aarón, Nadab y Abiú, tomaron cada uno su incensario, y pusieron fuego en ellos, sobre el cual pusieron perfume, y ofrecieron delante de Jehová fuego extraño, que él nunca les mandó. Y salió fuego de delante de Jehová que los quemó, y murieron delante de Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nadabe e Abiú"},"fr":{"text":"Nadab et Abihu"},"en":{"text":"Nadab and Abihu"},"es":{"text":"Nadab y 