select public.upsert_bank_question($json${"id":"pent-hard-009","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":14,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Que espia, além de Josué, rasgou as roupas depois de reconhecer a terra?","bible_ref":"Números 14:6","verse_text":"E Josué filho de Num, e Calebe filho de Jefoné, que eram dos que haviam reconhecido a terra, rasgaram suas roupas;"},"fr":{"prompt":"Quel espion, avec Josué, déchira ses vêtements après avoir exploré le pays ?","bible_ref":"Nombres 14:6","verse_text":"Et, parmi ceux qui avaient exploré le pays, Josué, fils de Nun, et Caleb, fils de Jephunné, déchirèrent leurs vêtements,"},"en":{"prompt":"Which spy, besides Joshua, tore his clothes after searching the land?","bible_ref":"Numbers 14:6","verse_text":"And Joshua the son of Nun, and Caleb the son of Jephunneh, which were of them that searched the land, rent their clothes:"},"es":{"prompt":"¿Qué espía, además de Josué, rasgó sus vestidos después de reconocer la tierra?","bible_ref":"Números 14:6","verse_text":"Y Josué hijo de Nun, y Caleb hijo de Jephone, que eran de los que habían reconocido la tierra, rompieron sus vestidos;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Coré"},"fr":{"text":"Koré"},"en":{"text":"Korah"},"es":{"text":"Coré"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Arão"},"fr":{"text":"Aaron"},"en":{"text":"Aaron"},"es":{"text":"Aarón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Eleazar"},"fr":{"text":"Éléazar"},"en":{"text":"Eleazar"},"es":{"text":"Eleazar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-hard-010","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":16,"verse_start":32,"verse_end":32,"texts":{"pt":{"prompt":"A terra abriu-se e tragou os homens de quem?","bible_ref":"Números 16:32","verse_text":"E abriu a terra sua boca, e tragou-os a eles, e a suas casas, e a todos os homens de Coré, e a todos os seus pertences."},"fr":{"prompt":"La terre ouvrit sa bouche et engloutit les gens de qui ?","bible_ref":"Nombres 16:32","verse_text":"La terre ouvrit sa bouche, et les engloutit, eux et leurs maisons, avec tous les gens de Koré et tous leurs biens."},"en":{"prompt":"The earth opened and swallowed up the men of whom?","bible_ref":"Numbers 16:32","verse_text":"And the earth opened her mouth, and swallowed them up, and their houses, and all the men that appertained unto Korah, and all their goods."},"es":{"prompt":"¿De quién eran los hombres que la tierra tragó al abrirse?","bible_ref":"Números 16:32","verse_text":"Y abrió la tierra su boca, y tragólos á ellos, y á sus casas, y á todos los hombres de Coré, y á toda su hacienda."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Coré"},"fr":{"text":"Koré"},"en":{"text":"Korah"},"es":{"text":"Coré"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Balaão"},"fr":{"text":"Balaam"},"en":{"text":"Balaam"},"es":{"text":"Balaam"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Balaque"},"fr":{"text":"Balak"},"en":{"text":"Balak"},"es":{"text":"Balac"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ogue"},"fr":{"text":"Og"},"en":{"text":"Og"},"es":{"text":"Og"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"pent-hard-011","type":"choice","level":"hard","testament":"ot","book":"NUM","chapter":20,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Em Números 20, quantas vezes feriu Moisés a rocha com a vara para sair água?","bible_ref":"Números 20:11","verse_text":"Então levantou Moisés sua mão, e feriu a rocha com sua vara duas vezes: e saíram muitas águas, e bebeu a congregação, e seus animais."},"fr":{"prompt":"En Nombres 20, combien de fois Moïse frappa-t-il le rocher avec sa verge pour en faire sortir de l’eau ?","bible_ref":"Nombres 20:11","verse_text":"Puis Moïse leva la main et frappa deux fois le rocher avec sa verge. Il sortit de l’eau en abondance. L’assemblée but, et le bétail aussi."},"en":{"prompt":"In Numbers 20, how many times did Moses strike the rock with his rod for water?","bible_ref":"Numbers 20:11","verse_text":"And Moses lifted up his hand, and with his rod he smote the rock twice: and the water came out abundantly, and the congregation drank, and their beasts also."},"es":{"prompt":"En Números 20, ¿cuántas veces golpeó Moisés la peña con su vara para que saliera agua?","bible_ref":"Números 20:11","verse_text":"Entonces alzó Moisés su mano, é hirió la peña con su vara dos veces: y salieron muchas aguas, y bebió la congregación, y sus bestias."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"2"},"fr":{"text":"2"},"en":{"text":"2"},"es":{"text":"2"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"1"},"fr":{"text":"1"},"en":{"text":"1"},"es":{"text":"1"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"3"},"fr":{"text":"3"},"en":{"text":"3"},"es":{"text":"3"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"7"},"fr":{"text":"7"},"en":{"text":"7"},"es":{"text":"7"}}}]}$json$::jsonb);
