select public.upsert_bank_question($json${"id":"pent-hard-018","type":"verse","level":"hard","testament":"ot","book":"LEV","chapter":17,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Porque a vida da _____ no sangue está: e eu vo-la dei para expiar vossas pessoas sobre o altar: pelo qual o mesmo sangue expiará a pessoa.","bible_ref":"Levítico 17:11","verse_text":"Porque a vida da carne no sangue está: e eu vo-la dei para expiar vossas pessoas sobre o altar: pelo qual o mesmo sangue expiará a pessoa."},"fr":{"prompt":"Car l’âme de la _____ est dans le sang. Je vous l’ai donné sur l’autel, afin qu’il servît d’expiation pour vos âmes, car c’est par l’âme que le sang fait l’expiation.","bible_ref":"Lévitique 17:11","verse_text":"Car l’âme de la chair est dans le sang. Je vous l’ai donné sur l’autel, afin qu’il servît d’expiation pour vos âmes, car c’est par l’âme que le sang fait l’expiation."},"en":{"prompt":"For the life of the _____ is in the blood: and I have given it to you upon the altar to make an atonement for your souls: for it is the blood that maketh an atonement for the soul.","bible_ref":"Leviticus 17:11","verse_text":"For the life of the flesh is in the blood: and I have given it to you upon the altar to make an atonement for your souls: for it is the blood that maketh an atonement for the soul."},"es":{"prompt":"Porque la vida de la _____ en la sangre está: y yo os la he dado para expiar vuestras personas sobre el altar: por lo cual la misma sangre expiará la persona.","bible_ref":"Levítico 17:11","verse_text":"Porque la vida de la carne en la sangre está: y yo os la he dado para expiar vuestras personas sobre el altar: por lo cual la misma sangre expiará la persona."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"terra"},"fr":{"text":"terre"},"en":{"text":"earth"},"es":{"text":"tierra"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"carne"},"fr":{"text":"chair"},"en":{"text":"flesh"},"es":{"text":"carne"}}},{"pos