select public.upsert_bank_question($json${"id":"pent-hard-019","type":"verse","level":"hard","testament":"ot","book":"NUM","chapter":23,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Deus não é homem, para que _____; nem filho de homem para que se arrependa: ele disse, e não fará? Falou, e não o executará?","bible_ref":"Números 23:19","verse_text":"Deus não é homem, para que minta; nem filho de homem para que se arrependa: ele disse, e não fará? Falou, e não o executará?"},"fr":{"prompt":"Dieu n’est point un homme pour _____, Ni fils d’un homme pour se repentir. Ce qu’il a dit, ne le fera-t-il pas? Ce qu’il a déclaré, ne l’exécutera-t-il pas?","bible_ref":"Nombres 23:19","verse_text":"Dieu n’est point un homme pour mentir, Ni fils d’un homme pour se repentir. Ce qu’il a dit, ne le fera-t-il pas? Ce qu’il a déclaré, ne l’exécutera-t-il pas?"},"en":{"prompt":"God is not a man, that he should _____; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?","bible_ref":"Numbers 23:19","verse_text":"God is not a man, that he should lie; neither the son of man, that he should repent: hath he said, and shall he not do it? or hath he spoken, and shall he not make it good?"},"es":{"prompt":"Dios no es hombre, para que _____; ni hijo de hombre para que se arrepienta: el dijo, ¿y no hará?; habló, ¿y no lo ejecutará?","bible_ref":"Números 23:19","verse_text":"Dios no es hombre, para que mienta; ni hijo de hombre para que se arrepienta: el dijo, ¿y no hará?; habló, ¿y no lo ejecutará?"}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"esqueça"},"fr":{"text":"oublier"},"en":{"text":"forget"},"es":{"text":"olvide"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"morra"},"fr":{"text":"mourir"},"en":{"text":"die"},"es":{"text":"muera"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"durma"},"fr":{"text":"dormir"},"en":{"text":"sleep"},"es":{"text":"duerma"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"minta"},"fr":{"text":"mentir"},"en":{"text":"lie"},"es":{"text":"mienta"}}}]}$json$::jsonb);
